 140:                     // There are many passwords out there that will also pass the validity checks we are able to perform.
 141:                     // This is a weakness of the ZipCrypto algorithm, due to its fairly primitive approach to cryptography.
 142:                     match archive.by_index_decrypt(file_number, &password_bytes) {
 143:                         // invalid password
 144:                         Err(ZipError::InvalidPassword) => (),
