   1: use crate::finder_errors::FinderError;
   2: use crate::password_gen::password_generator_count;
   3: use crate::password_mask::{ParsedMask, mask_password_count};
   4: use crate::password_reader::password_reader_count;
   5: use crate::password_worker::password_checker;
   6: use crate::zip_utils::validate_zip;
   7: use crate::{GenPasswords, MaskGenPasswords, PasswordFile};
   8: use indicatif::{ProgressBar, ProgressDrawTarget, ProgressStyle};
   9: use std::path::{Path, PathBuf};
  10: use std::sync::Arc;
  11: use std::sync::atomic::{AtomicBool, Ordering};
  12: use std::sync::mpsc::{Receiver, SyncSender, sync_channel};
  13: use zip_password_finder::password_gen::password_count_already_generated;
  14: 
  15: #[derive(Clone, Debug)]
  16: pub enum Strategy {
  17:     PasswordFile(PathBuf),
  18:     GenPasswords {
  19:         charset: Vec<char>,
  20:         min_password_len: usize,
  21:         max_password_len: usize,
  22:         starting_password: Option<String>,
  23:     },
  24:     MaskGenPasswords {
  25:         mask: ParsedMask,
  26:     },
  27: }
  28: 
  29: pub fn password_finder(
  30:     zip_path: &str,
  31:     workers: usize,
  32:     file_number: usize,
  33:     strategy: &Strategy,
  34:     stop_signal: Arc<AtomicBool>,
  35: ) -> Result<Option<String>, FinderError> {
  36:     let file_path = Path::new(zip_path);
  37: 
  38:     // Progress bar
  39:     let progress_bar = ProgressBar::new(0);
  40:     let progress_style = ProgressStyle::default_bar()
  41:         .template("[{elapsed_precise}] {wide_bar} {pos}/{len} throughput:{per_sec} (eta:{eta})")
  42:         .expect("Failed to create progress style");
  43:     progress_bar.set_style(progress_style);
  44:     // Refresh terminal 2 times per seconds
  45:     let draw_target = ProgressDrawTarget::stdout_with_hz(2);
  46:     progress_bar.set_draw_target(draw_target);
  47: 
  48:     // Fail early if the zip file is not valid
  49:     let validated_zip = validate_zip(file_path, file_number)?;
  50:     let file_number = validated_zip.file_number;
  51:     match &validated_zip.file_name {
  52:         Some(file_name) => {
  53:             progress_bar.println(format!("Targeting file '{file_name}' within the archive"));
  54:         }
  55:         None => progress_bar.println(format!(
  56:             "Cannot get file name from archive for --fileNumber {file_number}"
  57:         )),
  58:     }
  59: 
  60:     let aes_info = validated_zip.aes_info;
  61:     match &aes_info {
  62:         Some(aes_info) => progress_bar.println(format!(
  63:             "Archive encrypted with AES{} - expect a long wait time",
  64:             aes_info.aes_key_length * 8
  65:         )),
  66:         None => progress_bar
  67:             .println("Archive encrypted with ZipCrypto - expect a much faster throughput"),
  68:     }
  69: 
  70:     let (send_found_password, receive_found_password): (SyncSender<String>, Receiver<String>) =
  71:         sync_channel(1);
  72: 
  73:     let (total_password_count, skipped) = match strategy {
  74:         GenPasswords {
  75:             charset,
  76:             min_password_len,
  77:             max_password_len,
  78:             starting_password,
  79:         } => {
  80:             let mut skip = 0;
  81:             let total =
  82:                 password_generator_count(charset.len(), *min_password_len, *max_password_len);
  83:             if let Some(starting_password) = starting_password {
  84:                 skip =
  85:                     password_count_already_generated(charset, *min_password_len, starting_password);
  86:             }
  87:             (total, skip)
  88:         }
  89:         PasswordFile(password_list_path) => {
  90:             let total = password_reader_count(password_list_path.clone())?;
  91:             progress_bar.println(format!(
  92:                 "Using passwords dictionary {password_list_path:?} with {total} candidates."
  93:             ));
  94:             (total, 0)
  95:         }
  96:         MaskGenPasswords { mask } => {
  97:             let total = mask_password_count(mask);
  98:             progress_bar.println(format!("Using mask attack with {total} candidates."));
  99:             (total, 0)
 100:         }
 101:     };
 102: 
 103:     // set progress bar length according to the total number of passwords
 104:     progress_bar.set_length(total_password_count as u64);
 105:     // set progress bar position according to the number password skipped
 106:     progress_bar.set_position(skipped as u64);
 107:     // reset progress_bar speed
 108:     progress_bar.reset_elapsed();
 109: 
 110:     let mut worker_handles = Vec::with_capacity(workers);
 111: 
 112:     progress_bar.println(format!("Starting {workers} workers to test passwords"));
 113:     for i in 1..=workers {
 114:         let join_handle = password_checker(
 115:             i,
 116:             workers,
 117:             file_path,
 118:             file_number,
 119:             aes_info.clone(),
 120:             strategy.clone(),
 121:             send_found_password.clone(),
 122:             stop_signal.clone(),
 123:             progress_bar.clone(),
 124:         );
 125:         worker_handles.push(join_handle);
 126:     }
 127: 
 128:     // drop reference in `main` so that it disappears completely with workers for a clean shutdown
 129:     drop(send_found_password);
 130: 
 131:     // wait for password to be found
 132:     if let Ok(password_found) = receive_found_password.recv() {
 133:         // stop workers on success
 134:         stop_signal.store(true, Ordering::Relaxed);
 135:         for h in worker_handles {
 136:             h.join().unwrap();
 137:         }
 138:         progress_bar.finish_and_clear();
 139:         Ok(Some(password_found))
 140:     } else {
 141:         // workers are stopped by the signal
 142:         progress_bar.finish_and_clear();
 143:         Ok(None)
 144:     }
 145: }

